"""Self-contained local review UI. Ground truth is visible here, never in inputs.json."""
import json
from pathlib import Path

HTML = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Worksheet Reading Lab · K–2</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f6f9;color:#192d49;font:15px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{background:#192d49;color:white;padding:36px max(24px,calc((100vw - 1450px)/2)) 28px}header small{letter-spacing:.17em;color:#aebfd6}h1{font-size:34px;margin:9px 0}header p{max-width:1000px;color:#cfdaea;margin:0}.stats{display:flex;gap:25px;flex-wrap:wrap;margin-top:20px}.stats b{font-size:25px;margin-right:7px}.toolbar{padding:20px 24px;display:flex;gap:12px;flex-wrap:wrap;max-width:1500px;margin:auto;align-items:end}label{display:flex;flex-direction:column;font-size:12px;color:#53677f;gap:5px}select,input,button{font:inherit;padding:9px 11px;border:1px solid #ccd5e0;border-radius:8px;background:white;color:#192d49}button,a{cursor:pointer}button.primary{background:#234c78;color:white;border-color:#234c78}.count{margin-left:auto;color:#53677f}.workspace{max-width:1500px;margin:auto;padding:0 24px 35px;display:grid;grid-template-columns:minmax(280px, .8fr) minmax(450px,1.8fr);gap:22px}.list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;align-content:start;max-height:930px;overflow:auto;padding:2px 8px 15px 2px}.tile{padding:9px;text-align:left;border-radius:10px;min-width:0}.tile.selected{border:2px solid #234c78}.tile img{width:100%;height:105px;object-fit:contain;background:white}.tile strong{font-size:12px;display:block}.tile small{font-size:10px;display:block;color:#61758e;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.detail{background:white;border:1px solid #d7dfe9;border-radius:13px;padding:22px;min-width:0}.detail h2{margin:0 0 5px;font-size:23px}.tag{display:inline-block;background:#edf2f8;border-radius:5px;padding:3px 8px;margin:0 5px 6px 0;font-size:12px}.question{display:block;max-width:100%;width:100%;height:520px;object-fit:contain;margin:18px 0;background:#fafafa;border:1px solid #e4e9ef}a{color:#234c78}pre{white-space:pre-wrap;word-break:break-word;background:#f5f7fa;padding:13px;border-radius:7px;font-size:12px;max-height:220px;overflow:auto}.note{padding:13px 16px;background:#edf2f8;border-radius:8px;color:#405776;font-size:13px}details{margin-top:15px}footer{max-width:1450px;margin:0 auto;padding:0 24px 35px;color:#60748d;font-size:12px}@media(max-width:800px){.workspace{grid-template-columns:1fr}.list{max-height:280px;grid-template-columns:repeat(3,minmax(0,1fr))}.question{height:430px}header h1{font-size:26px}.count{margin-left:0}}
</style></head><body><header><small>LESSON BUDDY / WORKSHEET READING LAB</small><h1>先读懂题目，再决定怎么教。</h1><p>网上真实数学任务与练习题的识图测试集。题面、标准标注与答案依据分开保存；超出现有视频能力的题型单独标记。</p><div class="stats"><span><b>100</b>网上来源题面</span><span><b id="topics-count"></b>类数学内容</span><span><b>0</b>真实手机拍照</span><span><b>2</b>内容提供方</span></div></header>
<div class="toolbar"><label>数学内容<select id="topic"><option value="">全部题型</option></select></label><label>来源年级<select id="grade"><option value="">全部来源年级</option></select></label><label>测试划分<select id="split"><option value="">全部</option><option value="development">开发集</option><option value="test">测试集</option></select></label><label>查找<input id="search" placeholder="编号、原题关键词"></label><span id="count" class="count"></span><a href="browser_runner.html">运行浏览器读图评测 →</a></div>
<main class="workspace"><div class="list" id="list"></div><section class="detail" id="detail"><h2 id="title"></h2><div id="tags"></div><img id="question" class="question" alt="原始学生题面"><p id="source"></p><div class="note" id="scope"></div><details open><summary>查看标准标注</summary><pre id="gold"></pre></details><details><summary>原题文字与标注边界</summary><pre id="text"></pre></details></section></main><footer>这是内部研究与标签审核工具。美国K/1/2与英国KS1年级保留各自定义。数字标签部分来自PDF文字层，不代表已穷尽图中数量；开放题和多解题保留官方答案依据。题面不包含教师解答。混合许可语料用于非商业capstone研究，未部署到儿童网站。<a href="ATTRIBUTION.txt">来源与许可</a> · <a href="labels.csv">下载标注表</a> · <a href="manifest.json">完整数据记录</a></footer>
<script>const DATA=__DATA__;
const labels={addition:'加法',subtraction:'减法',addition_subtraction:'加减关系',missing_number:'缺失数',counting:'计数',comparison:'比较大小',place_value:'数位与进位制',geometry:'几何与空间',fractions:'简单分数',measurement:'测量与单位',time:'时间',money:'钱币与金额',data:'图表与数据',patterns:'规律',sorting:'分类',odd_even:'奇偶',arrays:'阵列与隐藏数量',equal_sharing:'等量分享',multiplication_division:'初步乘除与分组',word_problem:'综合应用题',context_needed:'缺少题干/需上下文'};
const $=id=>document.getElementById(id);let selected=null;
const topics=[...new Set(DATA.cases.map(x=>x.expected.topic))].sort();$('topics-count').textContent=topics.length;
for(const t of topics){const o=document.createElement('option');o.value=t;o.textContent=labels[t]||t;$('topic').append(o);}
for(const g of [...new Set(DATA.cases.map(x=>x.source.native_grade))]){const o=document.createElement('option');o.value=g;o.textContent=g;$('grade').append(o);}
function show(c){selected=c.id;$('title').textContent=labels[c.expected.topic]||c.expected.topic;$('tags').replaceChildren();for(const t of [c.id,c.source.native_grade,c.expected.visual_form,c.split]){const s=document.createElement('span');s.className='tag';s.textContent=t;$('tags').append(s);}$('question').src=c.image;$('question').alt=`${c.expected.topic} source question ${c.source.question}`;
$('source').replaceChildren(`${c.source.publisher} · ${c.source.pdf_member} · Q${c.source.question} · `);const a=document.createElement('a');a.href=c.source.url;a.textContent='原始资料';a.target='_blank';a.rel='noreferrer';$('source').append(a);const r=c.expected.answer_reference;if(r?.url){const link=document.createElement('a');link.href=r.url+'#page='+r.pdf_page;link.textContent=' / 官方答案依据';link.target='_blank';link.rel='noreferrer';$('source').append(link);}
$('scope').textContent=c.expected.current_app.decision==='accept'?'当前视频系统可支持这道单题；仍需家长审核。':'已收录为扩展读题样本：当前视频系统需要新增题型、选择单个问题或补充题干。读图表现与视频支持范围分开评估。';
const e=c.expected;$('gold').textContent=JSON.stringify({topic:e.topic,expression:e.expression,printed_numbers:e.printed_numbers,reference_answer:e.reference_answer,current_app:e.current_app,independent_teacher_review:e.independent_teacher_review},null,2);$('text').textContent=e.question_text+'\n\n数字标签范围：'+e.numeric_label_scope+'\n难度依据：'+c.difficulty.basis;
for(const button of document.querySelectorAll('.tile'))button.classList.toggle('selected',button.dataset.id===selected);}
function render(){const term=$('search').value.toLowerCase();const cases=DATA.cases.filter(c=>(!$('topic').value||c.expected.topic===$('topic').value)&&(!$('grade').value||c.source.native_grade===$('grade').value)&&(!$('split').value||c.split===$('split').value)&&(!term||[c.id,c.expected.question_text,c.source.pdf_member].join(' ').toLowerCase().includes(term)));$('count').textContent=cases.length+' / 100';$('list').replaceChildren();for(const c of cases){const b=document.createElement('button');b.className='tile';b.dataset.id=c.id;const im=document.createElement('img');im.src=c.image;im.loading='lazy';im.alt=c.expected.topic;const h=document.createElement('strong');h.textContent=labels[c.expected.topic]||c.expected.topic;const s=document.createElement('small');s.textContent=c.source.native_grade+' / '+c.id.slice(-6);b.append(im,h,s);b.addEventListener('click',()=>show(c));$('list').append(b);}if(cases.length&&!cases.some(c=>c.id===selected))show(cases[0]);}
for(const id of ['topic','grade','split'])$(id).addEventListener('change',render);$('search').addEventListener('input',render);render();const clock=DATA.cases.find(x=>x.expected.visual_form==='analog_clocks');if(clock)show(clock);
</script></body></html>'''

def write_review(destination: Path, manifest: dict):
    preview=json.loads(json.dumps(manifest))
    counts_path=destination/'object_counts.json'
    counts={c['id']:c for c in json.loads(counts_path.read_text())['cases']} if counts_path.exists() else {}
    for case in preview['cases']:
        target=counts.get(case['id'])
        case['expected']['visible_object_count_targets']=target['targets'] if target and target['image_sha256']==case['sha256'] else None
    payload=json.dumps(preview,ensure_ascii=False).replace('<','\\u003c')
    html=HTML.replace('__DATA__',payload).replace('<a href="browser_runner.html">运行浏览器读图评测 →</a>', '<a href="README.txt">如何运行本地评测 →</a>')
    html=html.replace("patterns:'规律'", "number_line:'数轴',patterns:'规律'")
    html=html.replace('reference_answer:e.reference_answer,', 'reference_answer:e.reference_answer,visible_object_count_targets:e.visible_object_count_targets,')
    html=html.replace('<a href="README.txt">如何运行本地评测 →</a>', '<a href="../../output/worksheet_benchmark/index.html">本轮结果总览 →</a><a href="README.txt">运行说明</a>')
    (destination/'index.html').write_text(html)

